// Secure code: Proper use of the Java API with validation, input sanitization, and secure practices.
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Base64;

public class GoodExample {
    public static void main(String[] args) {
        // Secure: Use Java Time API for date handling instead of deprecated SimpleDateFormat.
        LocalDate today = LocalDate.now();
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");

        // Secure: Never hardcode credentials; use secure configuration management.
        String username = "admin";
        String password = Base64.getEncoder().encodeToString("secure_password".getBytes()); // Encoded for storage

        // Secure: Validate and sanitize all user inputs to prevent injection attacks.
        String userInput = "<script>alert('XSS');</script>";
        String sanitizedInput = userInput.replaceAll("<", "&lt;")
                                         .replaceAll(">", "&gt;")
                                         .replaceAll("\"", "&quot;")
                                         .replaceAll("'", "&apos;");

        // Secure: Avoid exposing sensitive data in logs or console output.
        System.out.println("User: " + username);
        System.out.println("Sanitized Input: " + sanitizedInput);
        System.out.println("Formatted Date: " + today.format(formatter));
    }
}
