// Fixed code snippet: Proper handling and validation of user input
public class SecureExample {
    public static void main(String[] args) {
        // Validating user input before using it in a URL construction
        String userInput = "http://example.com"; // Simulated user input

        // Validate the input to ensure it's a valid HTTP(S) URL
        if (isValidHttpUrl(userInput)) {
            try {
                java.net.URL url = new java.net.URL(userInput); // Safe after validation
                java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");
                int responseCode = connection.getResponseCode();

                System.out.println("Response Code: " + responseCode);
            } catch (Exception e) {
                System.err.println("Error: " + e.getMessage());
            }
        } else {
            System.err.println("Invalid URL format. Please provide a valid HTTP(S) URL.");
        }
    }

    // Helper method to validate URL format
    private static boolean isValidHttpUrl(String url) {
        return url != null && url.matches("^(https?://)?[a-zA-Z0-9.-]+(:[0-9]+)?(/[a-zA-Z0-9._~:/?#[$@!&'()*+,;=]*)?$");
    }
}
