    }  
}  

// अच्छा कोड: फ़ाइल नाम के आधार पर एक सुरक्षित चेक करना  
public void saveFileSecure(String fileName) {  
    String safeFileName = fileName.replaceAll("[^a-zA-Z0-9_\\-\\.]", "_");  
    File file = new File(safeFileName);  
    // सुरक्षित फ़ाइल नाम के आधार पर फ़ाइल बनाना  
    try {  
        file.createNewFile();  
    } catch (IOException e) {  
        e.printStackTrace();  
    }  
}
