import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class VulnerableAPIUsage {

    public static void main(String[] args) {
        // Vulnerabile: Non si verifica la validità dell'URL e non si gestisce l'errore
        String url = "http://example.com/api/data?param=" + getUserInput(); // Input non filtrato

        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();
            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            System.out.println("Risposta ricevuta: " + response.toString());
        } catch (Exception e) {
            System.err.println("Errore durante la richiesta API: " + e.getMessage());
        }
    }

    private static String getUserInput() {
        return "test"; // Simulazione di input utente (non sicuro)
    }
}
