import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

public class SecureAPIUsage {

    public static void main(String[] args) {
        // Corretto: Filtraggio dell'input, gestione degli errori e sanitizzazione
        String userInput = getUserInput();
        String encodedInput = URLEncoder.encode(userInput, StandardCharsets.UTF_8); // Sanitizzazione dell'input

        String url = "http://example.com/api/data?param=" + encodedInput;

        try {
            URL obj = new URL(url);
            HttpURLConnection con = (HttpURLConnection) obj.openConnection();
            BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
            in.close();

            System.out.println("Risposta ricevuta: " + response.toString());
        } catch (Exception e) {
            System.err.println("Errore durante la richiesta API: " + e.getMessage());
        }
    }

    private static String getUserInput() {
        return "test"; // Simulazione di input utente (sicuro grazie alla sanitizzazione)
    }
}
