```java
// Corretto: utilizzo della valutazione sicura e gestione delle eccezioni appropriata
public class SafeServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String input = request.getParameter("input");

        // Valida l'input prima di usarlo
        if (input == null || input.trim().isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Input non valido");
            return;
        }

        // Usa un parser sicuro per evitare il rischio di esecuzione di codice non autorizzato
        try {
            ScriptEngine engine = new ScriptEngineManager().getEngineByName("JavaScript");
            engine.put("input", input);
            Object result = engine.eval("input"); // Espressione limitata e controllata
            response.getWriter().println("Risultato: " + result);
        } catch (ScriptException | NoSuchMethodException e) {
            // Gestione delle eccezioni con log dettagliato
            logger.error("Errore durante l'esecuzione del script: ", e);
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Errore nel processing del dato");
        }
    }
}
